export function latLonToWarsawWorld(
  lat: number,
  lon: number
): [number, number] {
  const rawKmX = (lon - WARSAW_GEO_CONFIG.centerLon) * (WARSAW_GEO_CONFIG.kmPerDegLon ?? 90);
  const rawKmZ = -(lat - WARSAW_GEO_CONFIG.centerLat) * (WARSAW_GEO_CONFIG.kmPerDegLat ?? 111.1);
  const distKm = Math.hypot(rawKmX, rawKmZ);
  const coreRadiusKm = WARSAW_GEO_CONFIG.coreRadiusKm ?? 7.5;
  const worldUnitsPerKm = WARSAW_GEO_CONFIG.worldUnitsPerKm ?? 10.8;
  let effectiveKm = distKm;
  if (distKm > coreRadiusKm) {
    effectiveKm = coreRadiusKm + Math.log1p((distKm - coreRadiusKm) * 0.30) * 5.6;
  }
  const scale = distKm > 0.0001 ? (effectiveKm / distKm) * worldUnitsPerKm : worldUnitsPerKm;
  return [Math.round(rawKmX * scale * 100) / 100, Math.round(rawKmZ * scale * 100) / 100];
}

